 journey={'stages':stages,'lanes':[{'label':'Treatment','cells':['Confirm indication, histology and plan','All four medicines','Nivolumab + pemetrexed + '+plat+'; NO ipilimumab','Nivolumab + ipilimumab; NO chemotherapy','Nivolumab only; NO ipilimumab or chemotherapy','Stop at progression/toxicity or up to 24 months; agree follow-up'],'kind':'treatment','source_ids':[c],'note':schedule}]+[dict(x,kind='monitoring',source_ids=[c],note='Relative stages; tests and treatment depend on review, not on calendar entry.') for x in rows], 'milestones':[{'title':'Baseline and first treatment','when':'Before Cycle 1 Day 1','why':'Confirm suitability and preventive medicines','clinical':' '.join(baseline),'action':'Confirm results, prescriptions, contacts and the actual chemotherapy backbone.','source_ids':[c]},{'title':'Final chemotherapy visit','when':'Cycle 1 Day 22 (21 days after first visit)','why':'Two chemotherapy administrations complete the planned induction','clinical':'Repeat FBC/renal/liver checks and review first-dose toxicity. No ipilimumab is due.','action':'Check next phase and stop/review chemotherapy support; continue folate for 21 days after final pemetrexed.','source_ids':[c]},{'title':'Immune continuation','when':'Cycle 2 onwards, Days 1 and 22','why':'Different medicines and support at alternating visits','clinical':'Day 1 nivolumab+ipilimumab, Day 22 nivolumab alone. Blood counts/kidney/liver every visit; glucose/TFT every 42-day cycle.','action':'Review joint immune hold rules and duration; maintain alert-card education.','source_ids':[c]},{'title':'End of treatment','when':'At progression, unacceptable toxicity or up to 24 months without progression','why':'Delayed immune effects and unresolved toxicities still need care','clinical':immune,'action':'Provide responsible-team, monitoring and urgent-contact arrangements.','source_ids':[c]}],'clinical_notes':limitations}
 am=[med('Aprepitant','125 mg orally on treatment day; 80 mg orally on each of the following two days','Repeat the three-day course separately around Cycle 1 Day 1 and Day 22'),med('Ondansetron','16 mg orally','Each chemotherapy treatment day','Review QT risk, interactions and individual dose choice.'),med('Antiemetic dexamethasone reference','12 mg orally on treatment day; 8 mg orally daily for the next three days','Repeat around both chemotherapy visits','Reconcile with pemetrexed rash steroids and aprepitant interaction into ONE prescription; do not add schedules.'),med('Metoclopramide','10 mg orally three times daily as prescribed','Subsequent days','NCIS high-risk row does not define an end day or PRN qualifier; prescriber must specify duration, suitability and interaction risks.')]
